61	// runCertJSON 以 --json 方式录入（或幂等重提）证书并解析结论。
62	func runCertJSON(t *testing.T, args []string) (result, certCLIResult) {
63		t.Helper()
64		r := runArgs(t, append(append([]string{}, args...), "--json")...)
65		var got certCLIResult
66		if r.code == 0 {
67			if err := json.Unmarshal([]byte(r.stdout), &got); err != nil {
68				t.Fatalf("cert JSON 解析失败: %v\n%s", err, r.stdout)
69			}
70		}
71		return r, got
72	}
